                    knownSum += table[j][i];
                }
            }

            if (unknownCount == 0) {
                continue;
            } else if (unknownCount == 1) {
                int diff = storeTotals[i] - knownSum;
                for (int j = 0; j < p; j++) {
                    if (table[j][i] == 0) {
                        results.push_back(diff);
                        break;
                    }
                }
            }
        }

        if (results.size() == countIf(table, 0)) {
            for (int i = 0; i < results.size(); i++) {
                cout << results[i] << endl;
            }
        } else {
            cout << "NO" << endl;
        }

        cout << endl;
    }

    return 0;
}

