using namespace std;

struct Artist {
    string name;
    int cost;
    int satisfaction;
};

int main() {
    int limit, n, m, x;
    while (cin >> limit >> n >> m >> x) {
        if (limit == 0 && n == 0 && m == 0 && x == 0) break;

        vector<Artist> secretArtists(n);
        vector<Artist> standardArtists(m);

        for (int i = 0; i < n; i++) {
            cin >> secretArtists[i].name >> secretArtists[i].cost >> secretArtists[i].satisfaction;
        }

        for (int i = 0; i < m; i++) {
            cin >> standardArtists[i].name >> standardArtists[i].cost >> standardArtists[i].satisfaction;
        }

        int maxSatisfaction = 0;

        // Select 0 secret artists
        {
            vector<int> dp(m + 1, -1);
            dp[0] = 0;
            for (int i = 0; i < m; i++) {
                for (int j = m; j >= 1; j--) {
                    if (dp[j - 1]!= -1 && dp[j - 1] + standardArtists[i].cost <= limit) {
                        dp[j] = max(dp[j], dp[j - 1] + standardArtists[i].satisfaction);
                    }
                }
            }
            maxSatisfaction = max(maxSatisfaction, dp[x]);
        }

        // Select 1 secret artist
        for (int i = 0; i < n; i++) {
            vector<int> dp(m + 1, -1);
            dp[0] = secretArtists[i].satisfaction;
            for (int j = 0; j < m; j++) {
                for (int k = m; k >= 1; k--) {
                    if (dp[k - 1]!= -1 && dp[k - 1] + standardArtists[j].cost <= limit - secretArtists[i].cost) {
                        dp[k] = max(dp[k], dp[k - 1] + standardArtists[j].satisfaction);
                    }
                }
            }
            maxSatisfaction = max(maxSatisfaction, dp[x]);
        }

        // Select 2 secret artists
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                vector<int> dp(m + 1, -1);
                dp[0] = secretArtists[i].satisfaction + secretArtists[j].satisfaction;
                for (int k = 0; k < m; k++) {
                    for (int l = m; l >= 1; l--) {
                        if (dp[l - 1]!= -1 && dp[l - 1] + standardArtists[k].cost <= limit - secretArtists[i].cost - secretArtists[j].cost) {
                            dp[l] = max(dp[l], dp[l - 1] + standardArtists[k].satisfaction);
                        }
                    }
                }
                maxSatisfaction = max(maxSatisfaction, dp[x]);
            }
        }

        cout << maxSatisfaction << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

const double EPS = 1e-10;

struct Point {
    double x, y;
};

double area(const vector<Point>& polygon) {
    int n = polygon.size();
    double area = 0.0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        area += polygon[i].x * polygon[j].y;
        area -= polygon[j].x * polygon[i].y;
    }
    return abs(area) / 2.0;
}

Point centroid(const vector<Point>& polygon) {
    int n = polygon.size();
    Point centroid;
    centroid.x = 0.0;
    centroid.y = 0.0;
    double area = 0.0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        double a = polygon[i].x * polygon[j].y - polygon[j].x * polygon[i].y;
        centroid.x += (polygon[i].x + polygon[j].x) * a;
        centroid.y += (polygon[i].y + polygon[j].y) * a;
        area += a;
    }
    area /= 3.0;
    centroid.x /= 6.0 * area;
    centroid.y /= 6.0 * area;
    return centroid;
}

int main() {
    int n;
    cin >> n;
    vector<Point> polygon(n);
    for (int i = 0; i < n; i++) {
        cin >> polygon[i].x >> polygon[i].y;
    }

    Point c = centroid(polygon);
    double totalArea = area(polygon);
    double halfArea = totalArea / 2.0;

    if (abs(totalArea - 2 * halfArea) > EPS) {
        cout << "NA" << endl;
        return 0;
    }

    cout << fixed;
    cout.precision(5);
    cout << c.x << " " << c.y << endl;

    return 0;
}

