bool check2(int x, int y, int z, int w) {
    vector<vector<int>> E(H, vector<int>(W, 0));
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (D[x + i][y + j] == 0) {
                E[x + i][y + j] = 1;
            } else if (D[x + i][y + j] == 1) {
                E[x + i][y + j] = 2;
            } else if (D[x + i][y + j] == 2) {
