long double minCost = numeric_limits<long double>::max();
int minCity;

void dfs(int u, int parent, long long sum, long double cost) {
    sum += weights[u];
    cost += weights[u] * sqrtl(weights[u]);

    if (cost < minCost) {
        minCost = cost;
        minCity = u;
    }

    for (const auto& edge : graph[u]) {
        if (edge.to!= parent) {
            dfs(edge.to, u, sum, cost);
