    sum += weights[u];
    cost += weights[u] * sqrtl(weights[u]);

    if (cost < minCost) {
        minCost = cost;
        minCity = u;
    }

    for (const auto& edge : graph[u]) {
        if (edge.to!= parent) {
            dfs2(edge.to, u, sum, cost + edge.weight * sqrtl(weights[u]));
        }
    }
}

