                for (int x = 1; x <= min(c, j); x++) {
                    dp[i + 1][j] = (dp[i + 1][j] + dp[i][j - x]) % MOD;
                }
            }
        }
    }

    int ans = 0;
    for (int i = 0; i <= m; i++) {
        ans = (ans + dp[i][k]) % MOD;
    }

    cout << ans << endl;

    return 0;
}

