        cin >> H >> R;
        if (H == 0 && R == 0) break;
        for (int i = 1; i <= H; i++) {
            cin >> hx[i] >> hy[i];
        }
        cin >> U >> M >> S >> du >> dm >> ds;
        for (int i = 1; i <= U; i++) {
