            cin >> sx[i] >> sy[i];
        }
        for (int i = 1; i <= R; i++) {
            cin >> w[i] >> a[i];
        }
        memset(ans, 0, sizeof(ans));
        for (int i = 1; i <= H; i++) {
            for (int j = 1; j <= R; j++) {
                bool ok = true;
                ok &= check(hx[i], hy[i], w[j], a[j], 0, 0, du);
                for (int k = 1; k <= U; k++) {
                    if (check(hx[i], hy[i], w[j], a[j], ux[k], uy[k], du)) {
                        ok = false;
                        break;
                    }
                }
                for (int k = 1; k <= M; k++) {
                    if (check2(hx[i], hy[i], w[j], a[j], mx[k], my[k], dm)) {
