const int INF = 1e9;

struct State {
    int board[3][3];
    int cost;
    int h;
    int v;
    int f;
    State* parent;

    State(int ch, int cv) : h(ch), v(cv), cost(0), f(0), parent(nullptr) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                board[i][j] = 0;
            }
        }
    }

    State(const State& other) : h(other.h), v(other.v), cost(other.cost), f(other.f), parent(other.parent) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                board[i][j] = other.board[i][j];
            }
        }
    }

    bool operator<(const State& other) const {
        return f > other.f;
    }

    bool operator==(const State& other) const {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j]!= other.board[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
};

int main() {
