                    for (int k = 0; k < right.size(); k++) {
                        for (int l = k + 1; l < right.size(); l++) {
                            if (gcd(right[k], right[l]) > 1) {
                                rightPossible = false;
                                break;
                            }
                        }
                        if (!rightPossible) break;
                    }

                    if (leftPossible && rightPossible) {
                        cout << "Yes" << endl;
                        return 0;
                    }
                }
            }
        }
    }

    cout << "No" << endl;
    return 0;
}

