    vector<int> c(n + m + 1);
    for (int i = 1; i <= n + m; ++i) {
        cin >> c[i];
    }

    vector<vector<int>> dp(n + 1, vector<int>(n + m + 1, -1e9));
    dp[0][0] = 0;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= n + m; ++j) {
            dp[i][j] = max(dp[i][j], dp[i - 1][j]);
            if (j >= l[i - 1]) {
                int cost = s[i - 1];
                int profit = c[l[i - 1]];
                if (j == l[i - 1]) {
                    profit += c[l[i - 1] + 1];
                }
                dp[i][j] = max(dp[i][j], dp[i - 1][j - 1] + profit - cost);
            }
        }
    }

    int ans = 0;
    for (int i = 0; i <= n + m; ++i) {
        ans = max(ans, dp[n][i]);
    }

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

const int MOD = 998244353;

long long power(long long a, long long b) {
    long long res = 1;
    while (b > 0) {
        if (b & 1) {
            res = (res * a) % MOD;
        }
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

long long inverse(long long a) {
    return power(a, MOD - 2);
}

long long C(int n, int k) {
    long long res = 1;
    for (int i = 1; i <= k; i++) {
        res = (res * (n - i + 1)) % MOD;
        res = (res * inverse(i)) % MOD;
    }
    return res;
}

int main() {
    int n, k;
    cin >> n >> k;

    if (k > n * (n - 1) / 2) {
        cout << 0 << endl;
        return 0;
    }

    long long ans = 0;
    for (int i = 0; i <= n; i++) {
        if (i * (i - 1) / 2 > k) {
            break;
        }
        int j = n - i;
        if (j * (j - 1) / 2 < k - i * (i - 1) / 2) {
            continue;
        }
        long long ways = C(n, i) * C(n - i, j) % MOD;
        ways = ways * power(i, i) % MOD;
        ways = ways * power(j, j) % MOD;
        ways = ways * power(2, k - i * (i - 1) / 2) % MOD;
        ways = ways * power(inverse(i), k - i * (i - 1) / 2) % MOD;
        ans = (ans + ways) % MOD;
    }

    cout << ans << endl;

    return 0;
}

