#include <bits/stdc++.h>
using namespace std;

const int maxn = 300005;

struct Edge {
    int v, w;
};

int n, m;
vector<Edge> g[maxn];
vector<int> w;
vector<int> order;

bool cmp(const Edge& a, const Edge& b) {
    return a.w < b.w;
}

void dfs(int u, int last_w) {
    for (auto& e : g[u]) {
        if (e.w > last_w) {
            w.push_back(e.w);
            dfs(e.v, e.w);
            w.pop_back();
        }
    }
}

int dp[maxn][maxn];

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 0; i < m; i++) {
        int u, v, wi;
        scanf("%d %d %d", &u, &v, &wi);
        g[u].push_back({v, wi});
    }

    for (int i = 1; i <= n; i++) {
        sort(g[i].begin(), g[i].end(), cmp);
    }

    int ans = 0;
    for (int u = 1; u <= n; u++) {
        memset(dp, 0, sizeof dp);
        for (auto& e : g[u]) {
            int len = 1;
            w.clear();
            w.push_back(e.w);
            dfs(e.v, e.w);
            for (int j = w.size() - 1; j >= 0; j--) {
                for (int k = 1; k <= n; k++) {
                    if (g[k].size() == 0) continue;
                    if (g[k][0].w > w[j]) {
                        dp[k][j + 1] = max(dp[k][j + 1], dp[k][0] + len + 1);
                    }
                }
                len++;
            }
            for (int j = 1; j <= n; j++) {
                ans = max(ans, dp[j][0]);
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

const int MAX_N = 505;
const int MAX_TIME = 2 * MAX_N;
const int MAX_WEIGHT = 1005;
const long long INF = LLONG_MAX;

struct Parcel {
    int in, out, weight, strength, value;
};

int n, S;
Parcel parcels[MAX_N];
long long dp[MAX_N][MAX_TIME][MAX_WEIGHT];

void init() {
    for (int i = 0; i < MAX_N; i++) {
        for (int j = 0; j < MAX_TIME; j++) {
            for (int k = 0; k < MAX_WEIGHT; k++) {
                dp[i][j][k] = -INF;
            }
        }
    }
    dp[0][0][0] = 0;
}

long long solve() {
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < MAX_TIME; j++) {
            for (int k = 0; k < MAX_WEIGHT; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
            }
        }
        for (int j = parcels[i - 1].in; j < MAX_TIME; j++) {
            for (int k = 0; k < MAX_WEIGHT; k++) {
                if (j == parcels[i - 1].out) {
                    if (k >= parcels[i - 1].weight && k - parcels[i - 1].weight <= parcels[i - 1].strength) {
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j][k - parcels[i - 1].weight] + parcels[i - 1].value);
                    }
                } else {
                    if (k + parcels[i - 1].weight <= S && k <= parcels[i - 1].strength) {
                        dp[i][j][k + parcels[i - 1].weight] = max(dp[i][j][k + parcels[i - 1].weight], dp[i][j][k]);
                    }
                }
            }
        }
    }
    long long ans = 0;
    for (int j = 0; j < MAX_TIME; j++) {
        for (int k = 0; k < MAX_WEIGHT; k++) {
            ans = max(ans, dp[n][j][k]);
        }
    }
    return ans;
}

int main() {
    cin >> n >> S;
    for (int i = 0; i < n; i++) {
        cin >> parcels[i].in >> parcels[i].out >> parcels[i].weight >> parcels[i].strength >> parcels[i].value;
    }
    init();
    cout << solve() << endl;
    return 0;
}

