pair<ll, ll> get_min(ll v, vector<ll> &used) {
    used[v] = 1;
    pair<ll, ll> ans = {a[v], v};
    for (auto to : g[v]) {
        if (!used[to.fi]) {
            auto cand = get_min(to.fi, used);
            cand.fi += to.se;
            if (cand.fi < ans.fi) ans = cand;
        }
    }
    return ans;
}

int main() {
