    while (cin >> n) {
        if (n == 0) break;

        vector<string> grid(n);
        for (int i = 0; i < n; ++i) {
            cin >> grid[i];
        }

        cout << maxSquareSize(grid) << endl;
    }

    return 0;
}

#include <iostream>
