#include <iostream>
#include <cmath>
#include <vector>
#include <algorithm>

using namespace std;

struct Block {
    double minx, miny, maxx, maxy, h;
};

bool check(double r, const vector<Block>& blocks, double sx, double sy, double ex, double ey) {
    for (const auto& block : blocks) {
        if (block.minx <= sx + r && sx - r <= block.maxx && block.miny <= sy + r && sy - r <= block.maxy) {
            return false;
        }
        if (block.minx <= ex + r && ex - r <= block.maxx && block.miny <= ey + r && ey - r <= block.maxy) {
            return false;
        }
        if (block.minx <= sx + r && sx - r <= block.maxx) {
            double dy = ey - sy;
            double dx = ex - sx;
            double k = dy / dx;
            double b = sy - k * sx;
            double y = k * block.minx + b;
            if (block.miny <= y + r && y - r <= block.maxy && block.h > r + abs(y - block.miny)) {
                return false;
            }
            y = k * block.maxx + b;
            if (block.miny <= y + r && y - r <= block.maxy && block.h > r + abs(y - block.miny)) {
                return false;
            }
        }
        if (block.miny <= sy + r && sy - r <= block.maxy) {
            double dy = ey - sy;
            double dx = ex - sx;
            double k = dy / dx;
            double b = sy - k * sx;
            double x = (block.miny - b) / k;
            if (block.minx <= x + r && x - r <= block.maxx && block.h > r + abs(x - block.minx)) {
                return false;
            }
            x = (block.maxy - b) / k;
            if (block.minx <= x + r && x - r <= block.maxx && block.h > r + abs(x - block.minx)) {
                return false;
            }
        }
    }
    return true;
}

int main() {
    int n;
    while (cin >> n) {
        if (n == 0) break;
        double sx, sy, ex, ey;
        cin >> sx >> sy >> ex >> ey;
        vector<Block> blocks(n);
        for (auto& block : blocks) {
            cin >> block.minx >> block.miny >> block.maxx >> block.maxy >> block.h;
        }
        double l = 0, r = 1000;
        for (int i = 0; i < 100; i++) {
            double mid = (l + r) / 2;
            if (check(mid, blocks, sx, sy, ex, ey)) {
                l = mid;
            } else {
                r = mid;
            }
        }
        printf("%.10f\n", l);
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

struct Point {
    double x, y;
};

struct Line {
    double a, b, c;
};

Line getLine(const Point& p1, const Point& p2) {
    Line line;
    line.a = p1.y - p2.y;
    line.b = p2.x - p1.x;
    line.c = p1.x * p2.y - p2.x * p1.y;
    return line;
}

double getDistance(const Point& p, const Line& line) {
    return abs(line.a * p.x + line.b * p.y + line.c) / sqrt(line.a * line.a + line.b * line.b);
}

Point reflect(const Point& p, const Line& line) {
    Point reflected;
    reflected.x = p.x - 2 * (line.a * p.x + line.b * p.y + line.c) * line.a / (line.a * line.a + line.b * line.b);
    reflected.y = p.y - 2 * (line.a * p.x + line.b * p.y + line.c) * line.b / (line.a * line.a + line.b * line.b);
    return reflected;
}

int main() {
    int k;
    while (cin >> k) {
        if (k == 0) break;
        vector<Point> points(k * 2);
        for (int i = 0; i < k * 2; i += 2) {
            cin >> points[i].x >> points[i].y >> points[i + 1].x >> points[i + 1].y;
        }
        Point pinhole;
        cin >> pinhole.x >> pinhole.y;
        vector<Point> pinholes;
        pinholes.push_back(pinhole);
        for (int i = 0; i < k; i++) {
            Line line = getLine(points[i * 2], points[i * 2 + 1]);
            vector<Point> newPinholes;
            for (const auto& p : pinholes) {
                if (getDistance(p, line) < 1e-6) {
                    newPinholes.push_back(p);
                } else {
                    newPinholes.push_back(p);
                    newPinholes.push_back(reflect(p, line));
                }
            }
            pinholes = newPinholes;
        }
        cout << pinholes.size() << endl;
    }
    return 0;
}

