        vector<pair<int, int>> points(n);
        for (int i = 0; i < n; i++) {
            cin >> points[i].first >> points[i].second;
        }

        bool possible = false;
        for (int i = 0; i < n; i++) {
            int count = 1;
            for (int j = 0; j < n; j++) {
                if (i!= j && abs(points[i].first - points[j].first) + abs(points[i].second - points[j].second) <= k) {
                    count++;
                }
            }
            if (count == n) {
                possible = true;
                break;
            }
        }

        if (!possible) {
            cout << -1 << endl;
            continue;
        }

        int ans = n;
        for (int i = 0; i < n; i++) {
            vector<bool> visited(n, false);
            queue<int> q;
            q.push(i);
            visited[i] = true;
            int count = 1;

            while (!q.empty()) {
                int curr = q.front();
                q.pop();

                for (int j = 0; j < n; j++) {
                    if (!visited[j] && abs(points[curr].first - points[j].first) + abs(points[curr].second - points[j].second) <= k) {
                        q.push(j);
                        visited[j] = true;
                        count++;
                    }
                }
            }

            if (count == n) {
                ans = 1;
                break;
            }
        }

        if (ans == n) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i!= j) {
