                        q.push(j);
                        visited[j] = true;
                        int count = 2;

                        while (!q.empty()) {
                            int curr = q.front();
                            q.pop();

                            for (int l = 0; l < n; l++) {
                                if (!visited[l] && abs(points[curr].first - points[l].first) + abs(points[curr].second - points[l].second) <= k) {
                                    q.push(l);
                                    visited[l] = true;
                                    count++;
                                }
                            }
                        }

                        if (count == n) {
                            ans = 2;
                            break;
                        }
                    }
                }
                if (ans == 2) break;
            }
        }

        cout << (ans == n? -1 : ans) << endl;
    }

    return 0;
}

#include <iostream>
