    vector<int> c(k);
    for (int i = 0; i < k; ++i) {
        cin >> c[i];
    }
    long long ans = 1;
    int sum = 0;
    for (int i = 0; i < k; ++i) {
        ans = ans * comb(sum + c[i] - 1, c[i] - 1) % MOD;
        sum += c[i];
    }
    cout << ans << endl;
    return 0;
}

