using namespace std;

const int MOD = 1e9 + 7;

int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int mul(int a, int b) {
    return (1LL * a * b) % MOD;
}

int binpow(int a, int b) {
    int res = 1;
    while (b) {
        if (b & 1) res = mul(res, a);
        a = mul(a, a);
        b >>= 1;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<int> dp(M + 1, 0);
    dp[0] = 1;

    for (int i = 0; i < N; ++i) {
        vector<int> ndp(M + 1, 0);
        for (int j = 0; j <= M; ++j) {
            ndp[j] = add(ndp[j], mul(dp[j], binpow(2, M - j)));
            if (j > 0) ndp[j] = add(ndp[j], mul(dp[j - 1], binpow(2, M - j)));
        }
        swap(dp, ndp);
    }

    cout << dp[M] << '\n';

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int N, K, S;
    cin >> N >> K >> S;

    int A[N];
    int sum = 0;
    for (int i = 0; i < N; i++) {
        A[i] = 1;
        sum++;
    }
    int pos = 0;
    while (sum < S && pos < N - 1) {
        if (sum + A[pos + 1] <= S) {
            sum += A[pos + 1] - 1;
            A[pos + 1] = S - sum;
        } else {
            A[pos + 1] = S - sum;
            sum = S;
        }
        pos++;
    }
    if (pos < N - 1 && sum == S) {
        int diff = S - A[N - 1];
        A[N - 1] = S;
        for (int i = 0; i < N - 1; i++) {
            A[i] -= diff / (N - 1);
        }
    }
    int count = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i; j < N; j++) {
            int tempSum = 0;
            for (int k = i; k <= j; k++) {
                tempSum += A[k];
            }
            if (tempSum == S) {
                count++;
            }
        }
    }
    if (count > K) {
        int diff = count - K;
        for (int i = 0; i < diff; i++) {
            A[i * 2 + 1] = S - (A[i * 2] + A[i * 2 + 2]);
        }
    }
    if (count < K) {
        int diff = K - count;
        for (int i = 0; i < N; i++) {
            if (A[i] == 1 && diff > 0) {
                A[i] = S;
                diff--;
            }
        }
    }
    for (int i = 0; i < N; i++) {
        cout << A[i] << " ";
    }
    cout << endl;
    return 0;
}

