using namespace std;

struct Node {
    long long sum, sum1, sum2, max1, max2;
    Node() {
        sum = 0;
        sum1 = 0;
        sum2 = 0;
        max1 = 0;
        max2 = 0;
    }
    Node(long long x, long long y) {
        sum = x + y;
        sum1 = max(x, 0LL);
        sum2 = max(y, 0LL);
        max1 = max(x, 0LL);
        max2 = max(y, 0LL);
    }
};

Node merge(Node x, Node y) {
    Node ans;
    ans.sum = x.sum + y.sum;
    ans.sum1 = x.sum1 + y.sum1;
    ans.sum2 = x.sum2 + y.sum2;
    ans.max1 = max(x.max1 + y.sum1, x.sum1 + y.max1);
    ans.max2 = max(x.max2 + y.sum2, x.sum2 + y.max2);
    return ans;
}

const int MAXN = 2e5 + 10;

long long a[MAXN], b[MAXN];
Node tree[4 * MAXN];

void update(int pos, int L, int R, int idx, long long x, long long y) {
    if (L == R) {
        tree[pos] = Node(x, y);
        return;
    }
    int mid = (L + R) / 2;
    if (idx <= mid) {
        update(2 * pos, L, mid, idx, x, y);
    } else {
        update(2 * pos + 1, mid + 1, R, idx, x, y);
    }
    tree[pos] = merge(tree[2 * pos], tree[2 * pos + 1]);
}

Node get(int pos, int L, int R, int l, int r) {
    if (l <= L && R <= r) {
        return tree[pos];
    }
    if (l > R || L > r) {
        return Node();
    }
    int mid = (L + R) / 2;
    return merge(get(2 * pos, L, mid, l, r), get(2 * pos + 1, mid + 1, R, l, r));
}

void build(int pos, int L, int R) {
    if (L == R) {
        tree[pos] = Node(a[L], b[L]);
        return;
    }
    int mid = (L + R) / 2;
    build(2 * pos, L, mid);
    build(2 * pos + 1, mid + 1, R);
    tree[pos] = merge(tree[2 * pos], tree[2 * pos + 1]);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int N, Q;
    cin >> N >> Q;
    N *= 2;
    for (int i = 0; i < N; ++i) {
        cin >> a[i];
    }
    for (int i = 0; i < N; ++i) {
        cin >> b[i];
    }
    build(1, 0, N - 1);
    for (int i = 0; i < Q; ++i) {
        int p, x, y;
        cin >> p >> x >> y;
        --p;
        update(1, 0, N - 1, p, x, y);
        cout << tree[1].max1 << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

struct Point {
    int x, y;
};

int find(vector<int>& parent, int i) {
    if (parent[i]!= i) {
        parent[i] = find(parent, parent[i]);
    }
    return parent[i];
}

void unionSet(vector<int>& parent, vector<int>& rank, int x, int y) {
    int xroot = find(parent, x);
    int yroot = find(parent, y);

    if (rank[xroot] < rank[yroot]) {
        parent[xroot] = yroot;
    } else if (rank[xroot] > rank[yroot]) {
        parent[yroot] = xroot;
    } else {
        parent[yroot] = xroot;
        rank[xroot]++;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Point> points(n);
    for (int i = 0; i < n; i++) {
        cin >> points[i].x >> points[i].y;
    }

    vector<pair<int, pair<int, int>>> edges;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int cost = min(abs(points[i].x - points[j].x), abs(points[i].y - points[j].y));
            edges.push_back({cost, {i, j}});
        }
    }

    sort(edges.begin(), edges.end());

    vector<int> parent(n);
    vector<int> rank(n, 0);
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }

    int result = 0;
    for (const auto& edge : edges) {
        int cost = edge.first;
        int u = edge.second.first;
        int v = edge.second.second;

        if (find(parent, u)!= find(parent, v)) {
            result += cost;
            unionSet(parent, rank, u, v);
        }
    }

    cout << result << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <limits>
#include <algorithm>

using namespace std;

const int INF = numeric_limits<int>::max();

struct Edge {
    int to, cost;
};

vector<vector<Edge>> graph;
vector<vector<int>> dist;

void dijkstra(int start) {
    vector<int> d(graph.size(), INF);
    d[start] = 0;
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        int v = pq.top().second;
        int cost = pq.top().first;
        pq.pop();

        if (cost > d[v]) continue;

        for (const auto& edge : graph[v]) {
            int to = edge.to;
            int newCost = cost + edge.cost;

            if (newCost < d[to]) {
                d[to] = newCost;
                pq.push({newCost, to});
            }
        }
    }

    dist[start] = d;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    graph.resize(N);
    dist.resize(N);

    for (int i = 0; i < M; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        a--, b--;

        graph[a].push_back({b, c});
        graph[b].push_back({a, c});
    }

    for (int i = 0; i < N; i++) {
        dijkstra(i);
    }

    int ans = 0;
    for (int i = 0; i < M; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        a--, b--;

        bool isShortest = false;
        for (int j = 0; j < N; j++) {
            for (int k = 0; k < N; k++) {
                if (j == k) continue;

                int shortest = dist[j][k];
                int shortestViaAB = dist[j][a] + c + dist[b][k];
                int shortestViaBA = dist[j][b] + c + dist[a][k];

                if (shortest == shortestViaAB || shortest == shortestViaBA) {
                    isShortest = true;
                    break;
                }
            }
            if (isShortest) break;
        }

        if (!isShortest) ans++;
    }

    cout << ans << endl;

    return 0;
}

